// https://emojibase.dev version 17.0.0

const b4a = require('b4a')
const { hostToLE16, hostToLE32 } = require('convert-endianness')

const INDEX = b4a.from('', 'base64')

exports.EMOJI_COUNT = 1949
exports.SKIN_COUNT = 475
exports.TAG_DICT_COUNT = 3638
exports.GROUP_COUNT = 10

exports.EMOJI_RECORDS = to32(0, 70164)
exports.SKIN_RECORDS = to32(70164, 79664)
exports.TAG_DICT = to32(79664, 94216)
exports.SHORTCODES = to32(94216, 107076)
exports.EMOTICONS = to32(107076, 107332)
exports.GROUPS = to32(107332, 107412)
exports.POINTS = to32(107412, 134660)
exports.TAG_REFS = to16(134660, 155084)
exports.STRINGS = INDEX.subarray(155084, 297107)

function to16 (offset, end) {
  const arr = new Uint16Array(INDEX.buffer, offset, (end - offset) / 2)
  hostToLE16(arr)
  return arr
}

function to32 (offset, end) {
  const arr = new Uint32Array(INDEX.buffer, offset, (end - offset) / 4)
  hostToLE32(arr)
  return arr
}
